<?php $isReturn = $transaction['transaction_type'] === 'customer_return'; ?>
<div class="mb-5 flex items-center gap-3"><a href="<?= e($isReturn&&$transaction['customer_id']?url('customers/'.$transaction['customer_id']):url('')) ?>" class="page-header-back">&larr;</a><div><h1 class="text-xl font-bold text-slate-900"><?= e($transaction['transaction_no']) ?></h1><p class="text-sm font-semibold uppercase text-brand-600"><?= e(str_replace('_',' ',$transaction['transaction_type'])) ?> · <?= e($transaction['status']) ?></p></div></div>
<div class="space-y-4">
  <?php if ($isReturn): ?><div class="hero-card hero-card-primary"><p class="text-xs uppercase text-brand-100">Customer</p><p class="mt-1 text-xl font-bold"><?= e($transaction['customer_name']) ?></p><div class="mt-4 grid grid-cols-2 gap-3 border-t border-white/20 pt-4"><div><p class="text-xs text-brand-100">Before</p><p class="font-bold">Rs. <?= number_format((float)$transaction['balance_before'],2) ?></p></div><div><p class="text-xs text-brand-100">After</p><p class="font-bold">Rs. <?= number_format((float)$transaction['balance_after'],2) ?></p></div></div></div><?php endif; ?>
  <?php foreach ($transaction['items'] as $item): ?><div class="card card-compact"><div class="flex justify-between"><div><p class="font-bold"><?= e($item['article_no']) ?></p><p class="text-xs text-slate-500"><?= $item['product_id']?'Registered product':'Manual article' ?> · Qty <?= (int)$item['quantity'] ?></p></div><p class="font-bold">Rs. <?= number_format((float)$item['line_total'],2) ?></p></div><?php if($item['previous_stock']!==null):?><div class="mt-3 flex justify-between rounded-xl bg-slate-50 p-3 text-xs"><span>Stock <?= (int)$item['previous_stock'] ?></span><strong><?= (int)$item['stock_delta']>=0?'+':'' ?><?= (int)$item['stock_delta'] ?></strong><span>New <?= (int)$item['new_stock'] ?></span></div><?php else:?><p class="mt-2 text-xs text-amber-700">Manual article recorded without creating or changing Product Master.</p><?php endif;?></div><?php endforeach; ?>
  <div class="card card-compact"><div class="flex justify-between text-lg"><span>Total</span><strong>Rs. <?= number_format((float)$transaction['grand_total'],2) ?></strong></div><p class="mt-2 text-xs text-slate-500">Recorded <?= e(date('j M Y, H:i',strtotime($transaction['created_at']))) ?><?= $transaction['created_by_name']?' by '.e($transaction['created_by_name']):'' ?></p></div>
  <?php if($isReturn):?><div class="grid grid-cols-2 gap-2"><a href="<?= e(url('customers/'.$transaction['customer_id'].'?tab=ledger')) ?>" class="btn btn-outline justify-center">View Customer Ledger</a><a href="<?= e(url('customers/'.$transaction['customer_id'].'/returns/create')) ?>" class="btn btn-primary justify-center">Add Another Return</a></div><?php endif;?>
</div>
